script:
frappe.ui.form.on("Customer", {
  setup(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  refresh(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  custom_project(frm) {
    frm.set_value("custom_plan", "");
  }
});

frappe.ui.form.on('Subscription Plan', {
	refresh(frm) {
        frm.set_query("add_on", "custom_addons", function(doc, cdt, cdn) {
            return {
                filters: {
                    custom_project: doc.custom_project,
                    custom_active: 1,
                    custom_subscription_type: "Addons"
                }
            };
        });
    }
})

frappe.ui.form.on('CRM Deal', {

	setup: function (frm) {
		set_custom_plan_query(frm);
	},

	refresh: function (frm) {
		set_custom_plan_query(frm);
		handle_won_deal_billing_state(frm);
	},

	status: function (frm) {
		handle_won_deal_billing_state(frm);
	},

	custom_sale_price: function (frm) {
		calculate_custom_amount(frm);
	},

	custom_paid_amount: function (frm) {
		// No need to check billing status on every change.
	},

	custom_plan: function (frm) {
		if (frm.doc.custom_plan) {

			frappe.db.get_value(
				'Subscription Plan',
				frm.doc.custom_plan,
				'cost',
				function (r) {

					if (r && r.cost !== undefined) {
						frm.set_value(
							'custom_original_price',
							r.cost
						);
					}

				}
			);
		}
	},

	custom_project: function (frm) {

		frm.set_value('custom_plan', '');

		set_custom_plan_query(frm);
	},

	validate: function (frm) {

		/*
		 * Payment validation
		 */
		if (frm.doc.custom_payment_status === 'Verify Payment') {

			let missing = [];

			if (flt(frm.doc.custom_paid_amount) <= 0) {
				missing.push(__('Paid Amount'));
			}

			if (!frm.doc.custom_payment_date) {
				missing.push(__('Payment Date'));
			}

			if (
				!frm.doc.custom_reference_number &&
				!frm.doc.custom_transaction_id
			) {
				missing.push(__('Reference Number'));
			}

			if (missing.length > 0) {

				frappe.msgprint({
					title: __('Missing Payment Information'),
					message: __(
						'The following fields are mandatory when Payment Status is set to "Verify Payment": {0}',
						[missing.join(', ')]
					),
					indicator: 'red'
				});

				frappe.validated = false;

				return;
			}
		}


		/*
		 * Won Deal protection
		 *
		 * The actual server-side validation should also
		 * enforce this rule.
		 */
		if (
			!frm.is_new() &&
			frm.doc.status === 'Won'
		) {

			/*
			 * If this flag has already been determined during
			 * refresh, use it.
			 */
			if (
				frm._billing_state_loaded &&
				!frm._billing_can_rerun
			) {

				frappe.msgprint({
					title: __('Deal Locked'),
					message: __(
						'This Deal has already completed its billing process and cannot be modified.'
					),
					indicator: 'red'
				});

				frappe.validated = false;

				return;
			}
		}
	}
});


/*
 * Subscription Plan Add Ons
 */
frappe.ui.form.on('Subscription Plan Add Ons', {

	amount: function (frm, cdt, cdn) {
		calculate_custom_amount(frm);
	},

	custom_addons_table_remove: function (frm, cdt, cdn) {
		calculate_custom_amount(frm);
	}
});


/*
 * Set Subscription Plan query based on Project
 */
function set_custom_plan_query(frm) {

	frm.set_query('custom_plan', function () {

		return {
			filters: {
				custom_project: frm.doc.custom_project || ''
			}
		};

	});
}


/*
 * Calculate Deal Amount
 *
 * Sale Price + Add-ons
 */
function calculate_custom_amount(frm) {

	let total = flt(frm.doc.custom_sale_price);

	if (frm.doc.custom_addons_table) {

		$.each(
			frm.doc.custom_addons_table,
			function (i, row) {

				total += flt(row.amount);

			}
		);
	}

	frm.set_value(
		'custom_amount',
		total
	);
}


/*
 * Check billing state of Won Deal
 */
function handle_won_deal_billing_state(frm) {

	/*
	 * Remove button first.
	 */
	frm.remove_custom_button(
		__('Re-run Billing Process')
	);


	/*
	 * Reset billing state.
	 */
	frm._billing_state_loaded = false;
	frm._billing_can_rerun = false;


	/*
	 * Only check saved Won Deals.
	 */
	if (
		frm.is_new() ||
		frm.doc.status !== 'Won'
	) {
		return;
	}


	frappe.call({

		method:
			'xpertintegration.api.integration.check_deal_billing_status',

		args: {
			deal_name: frm.doc.name
		},

		callback: function (r) {

			/*
			 * Mark billing state as loaded.
			 */
			frm._billing_state_loaded = true;


			const should_show_rerun =
				r.message &&
				r.message.should_show_rerun === true;


			frm._billing_can_rerun =
				should_show_rerun;


			/*
			 * Billing is already completed.
			 *
			 * No button.
			 *
			 * The validate event will prevent saving
			 * any modifications.
			 */
			if (!should_show_rerun) {

				return;
			}


			/*
			 * Billing can be re-run.
			 *
			 * Show the button.
			 */
			add_rerun_billing_button(frm);

		}
	});
}


/*
 * Add Re-run Billing Process button
 */
function add_rerun_billing_button(frm) {

	frm.add_custom_button(
		__('Re-run Billing Process'),
		function () {

			const sale_price = flt(
				frm.doc.custom_sale_price ||
				frm.doc.custom_amount
			);

			const paid_amount = flt(
				frm.doc.custom_paid_amount
			);


			frappe.confirm(

				__(
					'This will cancel existing Subscriptions, Sales Invoices, and Payment Entries for this deal and re-create them with Sale Price {0} and Paid Amount {1}. Are you sure you want to continue?',
					[
						format_currency(sale_price),
						format_currency(paid_amount)
					]
				),

				function () {

					frappe.call({

						method:
							'xpertintegration.api.integration.rerun_deal_subscription_process',

						args: {
							deal_name: frm.doc.name
						},

						freeze: true,

						freeze_message:
							__(
								'Re-running Subscription, Sales Invoice, and Payment Entry creation...'
							),

						callback: function (res) {

							if (res.message) {

								frappe.msgprint({

									title:
										__(
											'Billing Process Re-run Completed'
										),

									indicator: 'green',

									message: res.message

								});


								/*
								 * Reload the document.
								 *
								 * After successful billing,
								 * the Re-run button will disappear
								 * if the backend returns:
								 *
								 * should_show_rerun = false
								 */
								frm.reload_doc();

							}

						}

					});

				}
			);

		}
	).addClass('btn-warning');
}

frappe.ui.form.on("CRM Lead", {
	setup(frm) {
		set_lead_queries(frm);
	},
	refresh(frm) {
		set_lead_queries(frm);
		check_lead_duplicates(frm);
	},
	email(frm) {
		check_lead_duplicates(frm);
	},
	mobile_no(frm) {
		check_lead_duplicates(frm);
	},
	custom_project(frm) {
		frm.set_value("custom_plan", "");
		set_lead_queries(frm);
	},
});

function set_lead_queries(frm) {
	frm.set_query("custom_plan", function () {
		return {
			filters: {
				custom_project: frm.doc.custom_project || "",
				custom_subscription_type: ["!=", "Addons"],
				custom_active: 1,
			},
		};
	});
	frm.set_query("add_on", "custom_addons_table", function (doc, cdt, cdn) {
		return {
			filters: {
				custom_project: frm.doc.custom_project || "",
				custom_subscription_type: "Addons",
				custom_active: 1,
			},
		};
	});
}

function check_lead_duplicates(frm) {
	if (!frm.doc.email && !frm.doc.mobile_no) {
		frm.set_df_property("email", "description", "");
		frm.set_df_property("mobile_no", "description", "");
		return;
	}

	frappe.call({
		method: "xpertintegration.api.integration.check_lead_duplicates",
		args: {
			email: frm.doc.email,
			mobile_no: frm.doc.mobile_no,
			lead_id: frm.doc.name,
		},
		callback: function (r) {
			if (r && r.message) {
				if (r.message.email_exists) {
					frm.set_df_property(
						"email",
						"description",
						"<span style='color: #d97706; font-weight: 500;'>⚠️ " +
							r.message.email_message +
							"</span>"
					);
				} else {
					frm.set_df_property("email", "description", "");
				}

				if (r.message.mobile_exists) {
					frm.set_df_property(
						"mobile_no",
						"description",
						"<span style='color: #d97706; font-weight: 500;'>⚠️ " +
							r.message.mobile_message +
							"</span>"
					);
				} else {
					frm.set_df_property("mobile_no", "description", "");
				}
			}
		},
	});
}
